  function hexRgb(hex){let h=String(hex||'#5f927d').replace('#','');if(h.length===3)h=h.split('').map(x=>x+x).join('');const n=parseInt(h,16);return Number.isFinite(n)?[n>>16&255,n>>8&255,n&255]:[95,146,125]}
